  actor: Actor,''','''/** Tail of the import queue per organization; see `oneImportAtATime`. */
const importQueues = new Map<OrgId, Promise<void>>();

/**
 * Runs an org's imports strictly one after another. The checks an import makes
 * (has this key been imported? is there room under the quota?) are only true
 * for as long as no other import of the same org writes in between, and two
 * uploads of one key racing each other is exactly the case the key exists for.
 */
async function oneImportAtATime<T>(
  orgId: OrgId,
  task: () => Promise<T>,
): Promise<T> {
  const previous = importQueues.get(orgId) ?? Promise.resolve();
  const run = previous.then(task);
  const tail = run.then(
    () => undefined,
    () => undefined,
  );
  importQueues.set(orgId, tail);

  try {
    return await run;
  } finally {
    if (importQueues.get(orgId) === tail) importQueues.delete(orgId);
  }
}

/**
 * Bulk import: every row becomes an issue in the project, in file order, or
 * none does. The gates are `createIssue`'s — tenant scope, a live project,
 * `issue:create` — and then, for the batch as a whole, the per-project quota
 * and the issue-creation rate allowance (one unit per row). Nothing is
 * written until all of them pass, and the write itself is one transaction, so
 * a refused import leaves no issues, no labels and an unused key.
 *
 * A key this org has already imported is a replay: the first import's issues
 * come back and nothing is created, checked or announced again.
 *
 * One `issues.imported` is published per batch instead of an `issue.created`
 * per row; search, usage and the audit log subscribe to it, while
 * notifications and webhooks deliberately do not.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const { record, replayed } = await oneImportAtATime(input.orgId, () =>
    writeImport(actor, input, project),
  );

  if (replayed && record.projectId !== project.id) {
    // The key belongs to an upload into another project; its issues are only
    // handed back to someone who could have imported there too.
    const imported = requireFound(
      await projectRepo.findProjectById(input.orgId, record.projectId),
      "Project",
      record.projectId,
    );
