/**
 * Bulk issue import: all-or-nothing writes, replay by upload key, and the one
 * `issues.imported` announcement the rest of the product reacts to.
 *
 * The application's event handlers are attached exactly as the server does at
 * start-up, so search, usage, the audit log, notifications and webhooks are
 * the real subscribers.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { getPlanLimits } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { consumeRateLimit, getBucketConfig, resetRateLimits } from "@/lib/rate-limit";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { importIssuesSchema } from "@/schemas/issue-import";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { ImportIssueRowInput, ImportIssuesInput } from "@/schemas/issue-import";
import type { IsoTimestamp, OrgId, ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Project } from "@/types/project";

let cleanup: () => void;
let acme: Tenant;
let globex: Tenant;
let frugal: Tenant;
const detachers: Unsubscribe[] = [];
let keySeq = 0;

function nextKey(): string {
  keySeq += 1;
  return `upload-key-${keySeq}`;
}

function row(overrides: Partial<ImportIssueRowInput> = {}): ImportIssueRowInput {
  return {
    title: "Imported issue",
    description: null,
    status: "backlog",
    priority: "none",
    assigneeEmail: null,
    labels: [],
    dueAt: null,
    ...overrides,
  };
}

function batch(
  tenant: Tenant,
  rows: readonly ImportIssueRowInput[],
  overrides: Partial<ImportIssuesInput> = {},
): ImportIssuesInput {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    importKey: nextKey(),
    rows: [...rows],
    ...overrides,
  };
}

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

let projectSeq = 0;

async function freshProject(tenant: Tenant): Promise<Project> {
  projectSeq += 1;
  return projectRepo.insertProject({
    orgId: tenant.org.id,
    name: `Import target ${projectSeq}`,
    slug: `import-target-${projectSeq}`,
    key: `IMP${projectSeq}`,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

async function projectIssueCount(orgId: OrgId, projectId: ProjectId): Promise<number> {
  return issueRepo.countIssues(orgId, projectId, { includeArchived: true });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  acme = await createTenant("acme", "growth");
  globex = await createTenant("globex", "growth");
  frugal = await createTenant("frugal", "free");
  registerEventHandlers();
});

beforeEach(() => {
  resetRateLimits();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("importIssuesSchema", () => {
  it("applies the row defaults and lower-cases the assignee email", () => {
    const parsed = importIssuesSchema.parse({
      orgId: acme.org.id,
      projectId: acme.project.id,
      importKey: "upload-0001",
      rows: [{ title: "Only a title" }, { title: "With email", assigneeEmail: "Admin@Acme.Test" }],
    });

    expect(parsed.rows[0]).toEqual(row({ title: "Only a title" }));
    expect(parsed.rows[1]?.assigneeEmail).toBe("admin@acme.test");
  });

  it("bounds the key and the batch size", () => {
    const base = { orgId: acme.org.id, projectId: acme.project.id };
    const one = [{ title: "Row" }];

    expect(importIssuesSchema.safeParse({ ...base, importKey: "short", rows: one }).success).toBe(false);
    expect(importIssuesSchema.safeParse({ ...base, importKey: "upload-0001", rows: [] }).success).toBe(false);
    expect(
      importIssuesSchema.safeParse({
        ...base,
        importKey: "upload-0001",
        rows: Array.from({ length: 501 }, () => ({ title: "Row" })),
      }).success,
    ).toBe(false);
  });
});

describe("access", () => {
  it("refuses an orgId outside the actor's workspace", async () => {
    await expect(
      issueService.importIssues(acme.actors.member, batch(globex, [row()])),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("treats another workspace's project as not found", async () => {
    await expect(
      issueService.importIssues(
        acme.actors.member,
        batch(acme, [row()], { projectId: globex.project.id }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an archived project", async () => {
    const project = await freshProject(acme);
    await projectRepo.archiveProject(acme.org.id, project.id);

    await expect(
      issueService.importIssues(
        acme.actors.member,
        batch(acme, [row()], { projectId: project.id }),
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("needs the permission to create issues, and a refusal creates nothing", async () => {
    const project = await freshProject(acme);
    const seen = capture("issues.imported");

    await expect(
      issueService.importIssues(
        acme.actors.viewer,
        batch(acme, [row({ labels: ["viewer-made"] })], { projectId: project.id }),
      ),
    ).rejects.toThrow(/permission/i);

    expect(await projectIssueCount(acme.org.id, project.id)).toBe(0);
    expect((await labelRepo.listLabels(acme.org.id)).map((l) => l.name)).not.toContain("viewer-made");
    expect(seen).toHaveLength(0);
  });
});

describe("rows", () => {
  it("creates one issue per row, in file order, as the importer", async () => {
    const project = await freshProject(acme);
    const dueAt = "2026-12-24T10:00:00.000Z" as IsoTimestamp;

    const result = await issueService.importIssues(
      acme.actors.member,
      batch(
        acme,
        [
          row({ title: "First", description: "Details", status: "in_progress", priority: "urgent", dueAt }),
          row({ title: "Second" }),
          row({ title: "Third", status: "done" }),
        ],
        { projectId: project.id },
      ),
    );

    expect(result.replayed).toBe(false);
    expect(result.projectId).toBe(project.id);
    expect(result.issues.map((issue) => issue.title)).toEqual(["First", "Second", "Third"]);
    expect(result.issues.map((issue) => issue.number)).toEqual([1, 2, 3]);
    expect(result.issues[0]).toMatchObject({
      orgId: acme.org.id,
      projectId: project.id,
      description: "Details",
      status: "in_progress",
      priority: "urgent",
      dueAt,
      authorId: acme.userIds.member,
      assigneeId: null,
      parentId: null,
      estimate: null,
    });

    const stored = await issueRepo.findIssueById(acme.org.id, result.issues[2]!.id);
    expect(stored).toEqual(result.issues[2]);
  });

  it("numbers after the highest number ever used, and later creates continue", async () => {
    const project = await freshProject(acme);
    const first = await issueService.createIssue(
      acme.actors.member,
      issueInput(acme.org.id, project.id, { title: "Number one" }),
    );
    const second = await issueService.createIssue(
      acme.actors.member,
      issueInput(acme.org.id, project.id, { title: "Number two" }),
    );
    await issueService.archiveIssue(acme.actors.admin, acme.org.id, second.id);
    expect(first.number).toBe(1);

    const result = await issueService.importIssues(
      acme.actors.member,
      batch(acme, [row({ title: "Row A" }), row({ title: "Row B" })], { projectId: project.id }),
    );
    expect(result.issues.map((issue) => issue.number)).toEqual([3, 4]);

    const after = await issueService.createIssue(
      acme.actors.member,
      issueInput(acme.org.id, project.id, { title: "Number five" }),
    );
    expect(after.number).toBe(5);
  });

  it("assigns by active member email, case-insensitively, and never errors on a stranger", async () => {
    const project = await freshProject(acme);

    const removedUser = await userRepo.insertUser({
      email: "removed@acme.test",
      name: "Removed",
      passwordHash: "seed",
    });
    const removed = await memberRepo.insertMember(acme.org.id, removedUser.id, "member", null);
    await memberRepo.archiveMember(acme.org.id, removed.id);

    const result = await issueService.importIssues(
      acme.actors.member,
      batch(
        acme,
        [
          row({ title: "Mixed case", assigneeEmail: "Admin@ACME.test" }),
          row({ title: "Unknown address", assigneeEmail: "nobody@nowhere.test" }),
          row({ title: "Other workspace", assigneeEmail: "admin@globex.test" }),
          row({ title: "Removed member", assigneeEmail: "removed@acme.test" }),
        ],
        { projectId: project.id },
      ),
    );

    expect(result.issues.map((issue) => issue.assigneeId)).toEqual([
      acme.userIds.admin,
      null,
      null,
      null,
    ]);
  });

  it("matches labels by exact name inside the workspace and creates the missing ones once", async () => {
    const project = await freshProject(acme);
    const existing = await labelRepo.insertLabel({
      orgId: acme.org.id,
      name: "bug",
      color: "#ff0000",
      description: "Existing",
    });
    const foreign = await labelRepo.insertLabel({
      orgId: globex.org.id,
      name: "migrated",
      color: "#00ff00",
      description: null,
    });

    const result = await issueService.importIssues(
      acme.actors.member,
      batch(
        acme,
        [
          row({ title: "One", labels: ["bug", "migrated", "migrated"] }),
          row({ title: "Two", labels: ["migrated", "Bug"] }),
          row({ title: "Three" }),
        ],
        { projectId: project.id },
      ),
    );

    const labels = await labelRepo.listLabels(acme.org.id);
    const byName = new Map(labels.map((label) => [label.name, label]));
    expect(labels.filter((label) => label.name === "migrated")).toHaveLength(1);
    expect(byName.get("bug")?.id).toBe(existing.id);
    expect(byName.get("Bug")?.id).not.toBe(existing.id);
    expect(byName.get("migrated")).toMatchObject({ color: "#94a3b8", description: null });
    expect(byName.get("migrated")?.id).not.toBe(foreign.id);

    expect(result.issues[0]?.labelIds).toEqual([existing.id, byName.get("migrated")?.id]);
    expect(result.issues[1]?.labelIds).toEqual([byName.get("migrated")?.id, byName.get("Bug")?.id]);
    expect(result.issues[2]?.labelIds).toEqual([]);

    expect(await labelRepo.listLabels(globex.org.id)).toHaveLength(1);
  });
});

describe("all or nothing", () => {
  it("refuses a batch that would cross the per-project quota, like a single create at the limit", async () => {
    const limit = getPlanLimits("free").issuesPerProject;
    for (let n = 1; n <= limit - 2; n += 1) {
      await issueRepo.insertIssue(
        issueInput(frugal.org.id, frugal.project.id, { title: `Seed ${n}` }),
        frugal.userIds.member,
        n,
      );
    }

    const input = batch(frugal, [
      row({ title: "Fits", labels: ["quota-label"] }),
      row({ title: "Fits too" }),
      row({ title: "One too many" }),
    ]);
    const seen = capture("issues.imported");
    const allowanceBefore = (await consumeRateLimit(frugal.org.id, "issue:create", 0)).remaining;

    await expect(issueService.importIssues(frugal.actors.member, input)).rejects.toThrow(
      /allows no more issues/,
    );

    expect(await projectIssueCount(frugal.org.id, frugal.project.id)).toBe(limit - 2);
    expect(await labelRepo.listLabels(frugal.org.id)).toHaveLength(0);
    expect(seen).toHaveLength(0);
    expect((await consumeRateLimit(frugal.org.id, "issue:create", 0)).remaining).toBe(allowanceBefore);

    // The refusal did not use up the key: the same key is a first upload now.
    const retried = await issueService.importIssues(frugal.actors.member, {
      ...input,
      rows: input.rows.slice(0, 2),
    });
    expect(retried.replayed).toBe(false);
    expect(retried.issues).toHaveLength(2);

    await expect(
      issueService.createIssue(
        frugal.actors.member,
        issueInput(frugal.org.id, frugal.project.id, { title: "At the limit" }),
      ),
    ).rejects.toThrow(/allows no more issues/);
  });

  it("spends one unit of the issue-creation allowance per row", async () => {
    const project = await freshProject(acme);
    const before = (await consumeRateLimit(acme.org.id, "issue:create", 0)).remaining;

    await issueService.importIssues(
      acme.actors.member,
      batch(acme, [row(), row(), row()], { projectId: project.id }),
    );

    expect((await consumeRateLimit(acme.org.id, "issue:create", 0)).remaining).toBe(before - 3);
  });

  it("refuses a batch the allowance does not cover, creating nothing and keeping the key free", async () => {
    const project = await freshProject(acme);
    const { capacity } = getBucketConfig("issue:create");
    await consumeRateLimit(acme.org.id, "issue:create", capacity - 1);

    const input = batch(acme, [row({ labels: ["throttled"] }), row()], { projectId: project.id });
    await expect(issueService.importIssues(acme.actors.member, input)).rejects.toThrow(/rate limit/i);

    expect(await projectIssueCount(acme.org.id, project.id)).toBe(0);
    expect((await labelRepo.listLabels(acme.org.id)).map((l) => l.name)).not.toContain("throttled");

    resetRateLimits();
    const retried = await issueService.importIssues(acme.actors.member, input);
    expect(retried.replayed).toBe(false);
    expect(retried.issues).toHaveLength(2);
  });
});

describe("replays", () => {
  it("returns the first import for a key already used, whatever the rows now say", async () => {
    const project = await freshProject(acme);
    const input = batch(acme, [row({ title: "Alpha", labels: ["replay"] }), row({ title: "Beta" })], {
      projectId: project.id,
    });
    const first = await issueService.importIssues(acme.actors.member, input);

    const seen = capture("issues.imported");
    const allowance = (await consumeRateLimit(acme.org.id, "issue:create", 0)).remaining;
    const replay = await issueService.importIssues(acme.actors.member, {
      ...input,
      rows: [row({ title: "Something else entirely" })],
    });

    expect(replay.replayed).toBe(true);
    expect(replay.importKey).toBe(input.importKey);
    expect(replay.projectId).toBe(project.id);
    expect(replay.issues).toEqual(first.issues);
    expect(await projectIssueCount(acme.org.id, project.id)).toBe(2);
    expect(seen).toHaveLength(0);
    expect((await consumeRateLimit(acme.org.id, "issue:create", 0)).remaining).toBe(allowance);
  });

  it("imports identical rows again under a different key", async () => {
    const project = await freshProject(acme);
    const rows = [row({ title: "Same rows" })];

    const one = await issueService.importIssues(acme.actors.member, batch(acme, rows, { projectId: project.id }));
    const two = await issueService.importIssues(acme.actors.member, batch(acme, rows, { projectId: project.id }));

    expect(two.replayed).toBe(false);
    expect(two.issues[0]?.id).not.toBe(one.issues[0]?.id);
    expect(await projectIssueCount(acme.org.id, project.id)).toBe(2);
  });

  it("keeps keys per workspace", async () => {
    const importKey = nextKey();
    const inAcme = await issueService.importIssues(
      acme.actors.member,
      batch(acme, [row({ title: "Acme row" })], { importKey, projectId: (await freshProject(acme)).id }),
    );
    const inGlobex = await issueService.importIssues(
      globex.actors.member,
      batch(globex, [row({ title: "Globex row" })], { importKey }),
    );

    expect(inGlobex.replayed).toBe(false);
    expect(inGlobex.issues[0]?.orgId).toBe(globex.org.id);
    expect(inGlobex.issues[0]?.id).not.toBe(inAcme.issues[0]?.id);
  });

  it("creates one batch when the same key is uploaded twice at once", async () => {
    const project = await freshProject(acme);
    const input = batch(acme, [row({ title: "Raced" }), row({ title: "Raced too" })], {
      projectId: project.id,
    });
    const seen = capture("issues.imported");

    const [a, b] = await Promise.all([
      issueService.importIssues(acme.actors.member, input),
      issueService.importIssues(acme.actors.member, input),
    ]);

    expect([a.replayed, b.replayed].sort()).toEqual([false, true]);
    expect(a.issues.map((issue) => issue.id)).toEqual(b.issues.map((issue) => issue.id));
    expect(await projectIssueCount(acme.org.id, project.id)).toBe(2);
    expect(seen).toHaveLength(1);
  });
});

describe("announcements", () => {
  it("publishes one issues.imported, and everything downstream follows from it", async () => {
    const project = await freshProject(acme);
    const endpoint = await webhookRepo.insertEndpoint(
      {
        orgId: acme.org.id,
        url: "https://hooks.acme.test/taskflow",
        eventTypes: ["issue.created", "issue.updated", "issue.assigned", "issue.status_changed"],
      },
      "secret",
    );
    expect(endpoint.enabled).toBe(true);

    await usageService.recomputeUsage(acme.org.id);
    const usageBefore = await usageRepo.getUsage(acme.org.id);
    const pendingBefore = (await webhookRepo.listPendingDeliveries(acme.org.id, 100)).length;

    const imported = capture("issues.imported");
    const created = capture("issue.created");
    const assigned = capture("issue.assigned");

    const input = batch(
      acme,
      [
        row({ title: "Zeppelin maintenance", assigneeEmail: "admin@acme.test" }),
        row({ title: "Quokka census", description: "Count every xylophone" }),
      ],
      { projectId: project.id },
    );
    const result = await issueService.importIssues(acme.actors.member, input);

    expect(created).toHaveLength(0);
    expect(assigned).toHaveLength(0);
    expect(imported).toHaveLength(1);
    expect(imported[0]).toMatchObject({
      orgId: acme.org.id,
      actorId: acme.userIds.member,
      projectId: project.id,
      importKey: input.importKey,
      issueIds: result.issues.map((issue) => issue.id),
    });

    // Search
    for (const [q, issue] of [
      ["Zeppelin", result.issues[0]],
      ["xylophone", result.issues[1]],
    ] as const) {
      const hits = await searchService.search(acme.actors.member, {
        orgId: acme.org.id,
        q,
        limit: 25,
        cursor: null,
      });
      expect(hits.items.map((hit) => hit.id)).toEqual([issue?.id]);
    }

    // Usage
    const usageAfter = await usageRepo.getUsage(acme.org.id);
    expect(usageAfter.issuesUsed).toBe(usageBefore.issuesUsed + 2);
    expect((await usageRepo.recomputeUsage(acme.org.id)).issuesUsed).toBe(usageAfter.issuesUsed);

    // Audit log
    const audit = await activityRepo.listActivity({
      orgId: acme.org.id,
      projectId: project.id,
      limit: 100,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "issues.imported",
      actorId: acme.userIds.member,
      subjectKind: "project",
      subjectId: project.id,
      projectId: project.id,
      metadata: { count: 2, importKey: input.importKey },
    });

    // Nobody is notified, nothing is delivered.
    const inbox = await notificationRepo.listNotifications({
      orgId: acme.org.id,
      recipientId: acme.userIds.admin,
      limit: 100,
      cursor: null,
    });
    expect(inbox.items).toHaveLength(0);
    expect(await webhookRepo.listPendingDeliveries(acme.org.id, 100)).toHaveLength(pendingBefore);

    // A replay announces nothing further.
    await issueService.importIssues(acme.actors.member, input);
    expect(imported).toHaveLength(1);
    expect((await usageRepo.getUsage(acme.org.id)).issuesUsed).toBe(usageAfter.issuesUsed);
  });
});

